
import{actionLabel}from './action-icons.js';
import{esc}from './ui.js';
import{RUQYAH_RECORDINGS,ruqyahFor,ruqyahDuration}from './ruqyah-catalog.js';
import{ruqyahPlayback}from './ruqyah-session.js';
import{t}from './i18n.js';
import{uiLeaf,uiAttribute,setUiLabel,bindQuranUi}from './quran-ui.js';
export{RUQYAH_RECORDINGS,ruqyahFor,ruqyahDuration}from './ruqyah-catalog.js';
export function ruqyahMarkup(reciter){const records=ruqyahFor(reciter);if(!records.length)return '';return '<section class="reciter-ruqyah" '+uiAttribute('reciterUi.ruqyah')+'><div class="ruqyah-heading"><span class="eyebrow">'+uiLeaf('reciterUi.separateReading')+'</span><h2>'+uiLeaf('reciterUi.ruqyah')+'</h2></div>'+records.map(r=>'<article class="ruqyah-recording" data-ruqyah="'+r.id+'"><p>'+esc(r.title)+' <span class="ruqyah-duration">'+ruqyahDuration(r.duration)+'</span></p><div class="ruqyah-actions"><button type="button" class="button" data-ruqyah-play aria-pressed="false">'+actionLabel('play',t('quranUi.listen'))+'</button><a class="button secondary" href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer" download="salah-ruqyah-'+r.id+'.mp3">'+actionLabel('download',t('downloadUi.file'))+'</a></div><p class="ruqyah-status" role="status"></p></article>').join('')+'</section>';}
export function bindRuqyah(host,{session=ruqyahPlayback}={}){const cleanup=[],paints=[];for(const node of host.querySelectorAll('[data-ruqyah]')){const record=RUQYAH_RECORDINGS.find(r=>r.id===node.dataset.ruqyah);if(!record)continue;const button=node.querySelector('[data-ruqyah-play]'),status=node.querySelector('.ruqyah-status'),download=node.querySelector('a[download]');const play=()=>session.start(record.id);button.addEventListener('click',play);let current=session.state||{record:null};const paint=state=>{current=state;const own=state.record?.id===record.id,active=own&&['playing','loading'].includes(state.status);const icon=active?'pause':'play';if(button.dataset.uiPlayIcon!==icon){button.innerHTML=actionLabel(icon,'');button.dataset.uiPlayIcon=icon;}setUiLabel(button.querySelector('span'),active?'player.pause':'quranUi.listen');button.setAttribute('aria-pressed',String(active));const key=own?{loading:'reciterUi.openingRecording',paused:'player.pausedState',ended:'player.recordFinished',error:'reciterUi.recordingFailed'}[state.status]:null;if(key)setUiLabel(status,key);else{status.removeAttribute('data-quran-ui-key');status.textContent='';}setUiLabel(download.querySelector('span'),'downloadUi.file');};const unsubscribe=session.subscribe(paint);paints.push(()=>paint(current));cleanup.push(()=>{unsubscribe();button.removeEventListener('click',play);});}const offLanguage=bindQuranUi(host,()=>{for(const paint of paints)paint();});return()=>{offLanguage();for(const fn of cleanup)fn();};}
